/* Make all images responsive by default */
img, video, svg {
  max-width: 100%;   /* never wider than the container */
  height: auto;      /* maintain aspect ratio */
  display: block;    /* remove inline baseline gap */
}

/* object-fit — how image fills its container */
.card-image {
  width: 100%;
  height: 200px;        /* fixed container height */
  object-fit: cover;    /* fill the box, crop if needed */
  object-position: center top;  /* crop from top */
}

/* object-fit values:
   cover   — fill box, crop to maintain ratio (most common)
   contain — fit inside box, may letterbox
   fill    — stretch to fill (distorts)
   none    — natural size, may overflow */

/* Enforce consistent proportions */
.video-wrapper {
  width: 100%;
  aspect-ratio: 16 / 9;   /* widescreen video */
}

.avatar {
  width: 48px;
  aspect-ratio: 1;        /* perfect square */
  border-radius: 50%;     /* circle */
  object-fit: cover;
}

.card-image {
  width: 100%;
  aspect-ratio: 4 / 3;    /* photo card */
  object-fit: cover;
}

/* Auto-responsive card grid — NO media queries needed */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}

/* Fluid container with comfortable max-width */
.container {
  width: 100%;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 clamp(1rem, 5vw, 4rem);  /* fluid side padding */
}
